const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || {};
const chatId = source.chatId || message.chat?.id || '';
const raw = String(source.rawText || message.text || '').trim();
let cleaned = raw.replace(/^(tra loi mail|trả lời mail|tra loi email|trả lời email|reply mail|reply email)\s*/i, '').trim();
const parts = cleaned.split('\n').map((l) => l.trim()).filter(Boolean);
let searchQuery = '';
let replyBody = '';
let isReady = false;
if (parts.length >= 2) {
  searchQuery = parts[0];
  replyBody = parts.slice(1).join('\n');
  isReady = true;
} else if (parts.length === 1) {
  const spaceParts = parts[0].split(/\s{2,}|\t/);
  if (spaceParts.length >= 2) {
    searchQuery = spaceParts[0];
    replyBody = spaceParts.slice(1).join(' ');
    isReady = true;
  }
}
const guidance = '↩️ <b>Trả lời email</b>\n\nBạn hãy nhập:\n<code>trả lời mail [từ khóa tìm email]\n[nội dung trả lời]</code>\n\nVí dụ:\n<code>trả lời mail từ Google\nCảm ơn bạn đã liên hệ</code>';
return [{ json: { ...source, chatId, searchQuery, replyBody, isReady, response: isReady ? '' : guidance } }];

const source = $('Parse Tra Loi Email').item.json;

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
};

const rows = $input.all().map((i) => i.json || {}).filter((e) => e.id);
if (!rows.length) {
  return [{ json: { ...source, canReply: false, response: '⚠️ Không tìm thấy email để trả lời.' } }];
}
const email = rows[0];
const subject = pickFirst(email.subject, email.Subject, email.payload?.headers?.find((h) => h.name === 'Subject')?.value);
const threadId = email.threadId || email.id || '';
return [{ json: { ...source, canReply: true, messageId: email.id, threadId, subject } }];

const source = $('Parse Tra Loi Email').item.json;
const reply = $('Chon Email Reply').item.json;
const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');

const threadId = reply.threadId || '';
const link = threadId ? `https://mail.google.com/mail/u/0/#inbox/${threadId}` : '';

let text = '✅ <b>Đã trả lời email</b>\n\n';
if (reply.subject) text += `📝 Re: ${escapeHtml(reply.subject)}\n`;
text += `📄 ${escapeHtml(source.replyBody.substring(0, 200))}`;
if (source.replyBody.length > 200) text += '...';
if (link) text += `\n🔗 <a href="${escapeHtml(link)}">Xem cuộc trò chuyện</a>`;
return [{ json: { chatId: source.chatId, text } }];
